def _ledger(sequence_first, original_tax):
    def solve(data):
        chosen = {}
        cutoff = data.get("cutoff", 10**9)
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            revision = event.get("revision", 0)
            key = ((sequence, revision, position) if sequence_first
                   else (revision, position))
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = _round(raw * (10000 - discount), 10000, data["rounding"])
            tax_base = raw if original_tax else net
            tax = _round(tax_base * event.get("tax_bp", 0), 10000,
                         data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_06():
    from itertools import product

    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows_by_name = {
            name: {row["version"]: row for row in packages[name]}
            for name in names
        }
        options = [[None] + packages[name] for name in names]
        best_vector = None
        best_versions = None

        for selection in product(*options):
            chosen = {name: row for name, row in zip(names, selection)
                      if row is not None}
            versions = {name: row["version"] for name, row in chosen.items()}
            if any(versions.get(name) is None or not low <= versions[name] <= high
                   for name, (low, high) in data["roots"].items()):
                continue
            if any(name in versions and
                   (versions[name] in blocked.get(name, []) or
                    (name in pins and versions[name] != pins[name]))
                   for name in names):
                continue

            edges = {name: [] for name in chosen}
            valid = True
            for name, row in chosen.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    version = versions.get(target)
                    if version is None or not dep["min"] <= version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            active, finished = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(target) for target in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if any(not visit(name) for name in chosen):
                continue

            reachable = set()
            pending = list(data["roots"])
            while pending:
                name = pending.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                pending.extend(edges[name])
            if reachable != set(chosen):
                continue

            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector < best_vector:
                best_vector, best_versions = vector, versions

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_07():
    from itertools import combinations

    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None

        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids) or ids & blocked:
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["end"] > ordered[i + 1]["start"]
                   for i in range(len(ordered) - 1)):
                continue
            selected = sorted(ids)
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and selected > best_ids)):
                best_value, best_ids = value, selected

        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        required_bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = required_bit.get(source, 0)
        initial = (source, initial_mask, data["coupons"])
        distances = {initial: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, remaining - 1))
                next_mask = mask | required_bit.get(edge["v"], 0)
                for duration, next_remaining in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, *next_state))
        return {"arrival": None}
    return solve


